import{_ as o,c as r,o as n,j as s,Y as a,t as i}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"git-pull | x-cmd man (git man1) | Fetch from and integrate with another repository or a local","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-pull - Fetch from and integrate with another repository or a local","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-pull | x-cmd man (git man1) | Fetch from and integrate with another repository or a local"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-pull - Fetch from and integrate with another repository or a local"}]]},"headers":[],"params":{"isMan":true,"man":"git-pull","category":"git man1","desc":"Fetch from and integrate with another repository or a local"},"relativePath":"git/man1/git-pull.md","filePath":"git/man1/[man].md"}'),h={name:"git/man1/git-pull.md"},l={class:"visually-hidden"};function c(t,e,g,p,u,d){return n(),r("div",null,[s("h1",l,i(t.$params.man),1),e[0]||(e[0]=a(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-pull - Fetch from and integrate with another repository or a local branch</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">repository</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">refspec</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...]]</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Incorporates changes from a remote repository into the current branch. If the current branch is behind the remote, then by default it will fast-forward the current branch to match the remote. If the current branch and the remote have diverged, the user needs to specify how to reconcile the divergent branches with <strong>--rebase</strong> or <strong>--no-rebase</strong> (or the corresponding configuration option in <strong>pull.rebase</strong>).</p><p>More precisely, <strong>git pull</strong> runs <strong>git fetch</strong> with the given parameters and then depending on configuration options or command line flags, will call either <strong>git rebase</strong> or <strong>git merge</strong> to reconcile diverging branches.</p><p>&lt;repository&gt; should be the name of a remote repository as passed to <strong>git-fetch</strong>(1). &lt;refspec&gt; can name an arbitrary remote ref (for example, the name of a tag) or even a collection of refs with corresponding remote-tracking branches (e.g., refs/heads/*:refs/remotes/origin/*), but usually it is the name of a branch in the remote repository.</p><p>Default values for &lt;repository&gt; and &lt;branch&gt; are read from the &quot;remote&quot; and &quot;merge&quot; configuration for the current branch as set by <strong>git-branch</strong>(1) <strong>--track</strong>.</p><p>Assume the following history exists and the current branch is &quot;<strong>master</strong>&quot;:</p><blockquote><pre><code>          A---B---C master on origin
         /
    D---E---F---G master
        ^
        origin/master in your repository
</code></pre></blockquote><p>Then &quot;<strong>git pull</strong>&quot; will fetch and replay the changes from the remote <strong>master</strong> branch since it diverged from the local <strong>master</strong> (i.e., <strong>E</strong>) until its current commit (<strong>C</strong>) on top of <strong>master</strong> and record the result in a new commit along with the names of the two parent commits and a log message from the user describing the changes.</p><blockquote><pre><code>          A---B---C origin/master
         /          &lt;br&gt; &gt;         D---E---F---G---H master
</code></pre></blockquote><p>See <strong>git-merge</strong>(1) for details, including how conflicts are presented and handled.</p><p>In Git 1.7.0 or later, to cancel a conflicting merge, use <strong>git reset --merge</strong>. <strong>Warning</strong>: In older versions of Git, running <em>git pull</em> with uncommitted changes is discouraged: while possible, it leaves you in a state that may be hard to back out of in the case of a conflict.</p><p>If any of the remote changes overlap with local uncommitted changes, the merge will be automatically canceled and the work tree untouched. It is generally best to get any local changes in working order before pulling or stash them away with <strong>git-stash</strong>(1).</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-q, --quiet</p><blockquote><p>This is passed to both underlying git-fetch to squelch reporting of during transfer, and underlying git-merge to squelch output during merging.</p></blockquote><p>-v, --verbose</p><blockquote><p>Pass --verbose to git-fetch and git-merge.</p></blockquote><p>--[no-]recurse-submodules[=yes|on-demand|no]</p><blockquote><p>This option controls if new commits of populated submodules should be fetched, and if the working trees of active submodules should be updated, too (see <strong>git-fetch</strong>(1), <strong>git-config</strong>(1) and <strong>gitmodules</strong>(5)).</p><p>If the checkout is done via rebase, local submodule commits are rebased as well.</p><p>If the update is done via merge, the submodule conflicts are resolved and checked out.</p></blockquote><h3 id="options-related-to-merging" tabindex="-1">Options related to merging <a class="header-anchor" href="#options-related-to-merging" aria-label="Permalink to &quot;Options related to merging&quot;">​</a></h3><p>--commit, --no-commit</p><blockquote><p>Perform the merge and commit the result. This option can be used to override --no-commit. Only useful when merging.</p><p>With --no-commit perform the merge and stop just before creating a merge commit, to give the user a chance to inspect and further tweak the merge result before committing.</p><p>Note that fast-forward updates do not create a merge commit and therefore there is no way to stop those merges with --no-commit. Thus, if you want to ensure your branch is not changed or updated by the merge command, use --no-ff with --no-commit.</p></blockquote><p>--edit, -e, --no-edit</p><blockquote><p>Invoke an editor before committing successful mechanical merge to further edit the auto-generated merge message, so that the user can explain and justify the merge. The <strong>--no-edit</strong> option can be used to accept the auto-generated message (this is generally discouraged).</p><p>Older scripts may depend on the historical behaviour of not allowing the user to edit the merge log message. They will see an editor opened when they run <strong>git merge</strong>. To make it easier to adjust such scripts to the updated behaviour, the environment variable <strong>GIT_MERGE_AUTOEDIT</strong> can be set to <strong>no</strong> at the beginning of them.</p></blockquote><p>--cleanup=&lt;mode&gt;</p><blockquote><p>This option determines how the merge message will be cleaned up before committing. See <strong>git-commit</strong>(1) for more details. In addition, if the <em>&lt;mode&gt;</em> is given a value of <strong>scissors</strong>, scissors will be appended to <strong>MERGE_MSG</strong> before being passed on to the commit machinery in the case of a merge conflict.</p></blockquote><p>--ff-only</p><blockquote><p>Only update to the new history if there is no divergent local history. This is the default when no method for reconciling divergent histories is provided (via the --rebase=* flags).</p></blockquote><p>--ff, --no-ff</p><blockquote><p>When merging rather than rebasing, specifies how a merge is handled when the merged-in history is already a descendant of the current history. If merging is requested, <strong>--ff</strong> is the default unless merging an annotated (and possibly signed) tag that is not stored in its natural place in the <strong>refs/tags/</strong> hierarchy, in which case <strong>--no-ff</strong> is assumed.</p><p>With <strong>--ff</strong>, when possible resolve the merge as a fast-forward (only update the branch pointer to match the merged branch; do not create a merge commit). When not possible (when the merged-in history is not a descendant of the current history), create a merge commit.</p><p>With <strong>--no-ff</strong>, create a merge commit in all cases, even when the merge could instead be resolved as a fast-forward.</p></blockquote><p>-S[&lt;keyid&gt;], --gpg-sign[=&lt;keyid&gt;], --no-gpg-sign</p><blockquote><p>GPG-sign the resulting merge commit. The <strong>keyid</strong> argument is optional and defaults to the committer identity; if specified, it must be stuck to the option without a space. <strong>--no-gpg-sign</strong> is useful to countermand both <strong>commit.gpgSign</strong> configuration variable, and earlier <strong>--gpg-sign</strong>.</p></blockquote><p>--log[=&lt;n&gt;], --no-log</p><blockquote><p>In addition to branch names, populate the log message with one-line descriptions from at most &lt;n&gt; actual commits that are being merged. See also <strong>git-fmt-merge-msg</strong>(1). Only useful when merging.</p><p>With --no-log do not list one-line descriptions from the actual commits being merged.</p></blockquote><p>--signoff, --no-signoff</p><blockquote><p>Add a <strong>Signed-off-by</strong> trailer by the committer at the end of the commit log message. The meaning of a signoff depends on the project to which you&#39;re committing. For example, it may certify that the committer has the rights to submit the work under the project&#39;s license or agrees to some contributor representation, such as a Developer Certificate of Origin. (See <strong><a href="http://developercertificate.org" target="_blank" rel="noreferrer">http://developercertificate.org</a></strong> for the one used by the Linux kernel and Git projects.) Consult the documentation or leadership of the project to which you&#39;re contributing to understand how the signoffs are used in that project.</p><p>The --no-signoff option can be used to countermand an earlier --signoff option on the command line.</p></blockquote><p>--stat, -n, --no-stat</p><blockquote><p>Show a diffstat at the end of the merge. The diffstat is also controlled by the configuration option merge.stat.</p><p>With -n or --no-stat do not show a diffstat at the end of the merge.</p></blockquote><p>--squash, --no-squash</p><blockquote><p>Produce the working tree and index state as if a real merge happened (except for the merge information), but do not actually make a commit, move the <strong>HEAD</strong>, or record <strong>$GIT_DIR/MERGE_HEAD</strong> (to cause the next <strong>git commit</strong> command to create a merge commit). This allows you to create a single commit on top of the current branch whose effect is the same as merging another branch (or more in case of an octopus).</p><p>With --no-squash perform the merge and commit the result. This option can be used to override --squash.</p><p>With --squash, --commit is not allowed, and will fail.</p><p>Only useful when merging.</p></blockquote><p>--[no-]verify</p><blockquote><p>By default, the pre-merge and commit-msg hooks are run. When <strong>--no-verify</strong> is given, these are bypassed. See also <strong>githooks</strong>(5). Only useful when merging.</p></blockquote><p>-s &lt;strategy&gt;, --strategy=&lt;strategy&gt;</p><blockquote><p>Use the given merge strategy; can be supplied more than once to specify them in the order they should be tried. If there is no <strong>-s</strong> option, a built-in list of strategies is used instead (<strong>ort</strong> when merging a single head, <strong>octopus</strong> otherwise).</p></blockquote><p>-X &lt;option&gt;, --strategy-option=&lt;option&gt;</p><blockquote><p>Pass merge strategy specific option through to the merge strategy.</p></blockquote><p>--verify-signatures, --no-verify-signatures</p><blockquote><p>Verify that the tip commit of the side branch being merged is signed with a valid key, i.e. a key that has a valid uid: in the default trust model, this means the signing key has been signed by a trusted key. If the tip commit of the side branch is not signed with a valid key, the merge is aborted.</p><p>Only useful when merging.</p></blockquote><p>--summary, --no-summary</p><blockquote><p>Synonyms to --stat and --no-stat; these are deprecated and will be removed in the future.</p></blockquote><p>--autostash, --no-autostash</p><blockquote><p>Automatically create a temporary stash entry before the operation begins, record it in the special ref <strong>MERGE_AUTOSTASH</strong> and apply it after the operation ends. This means that you can run the operation on a dirty worktree. However, use with care: the final stash application after a successful merge might result in non-trivial conflicts.</p></blockquote><p>--allow-unrelated-histories</p><blockquote><p>By default, <strong>git merge</strong> command refuses to merge histories that do not share a common ancestor. This option can be used to override this safety when merging histories of two projects that started their lives independently. As that is a very rare occasion, no configuration variable to enable this by default exists and will not be added.</p><p>Only useful when merging.</p></blockquote><p>-r, --rebase[=false|true|merges|interactive]</p><blockquote><p>When true, rebase the current branch on top of the upstream branch after fetching. If there is a remote-tracking branch corresponding to the upstream branch and the upstream branch was rebased since last fetched, the rebase uses that information to avoid rebasing non-local changes.</p><p>When set to <strong>merges</strong>, rebase using <strong>git rebase --rebase-merges</strong> so that the local merge commits are included in the rebase (see <strong>git-rebase</strong>(1) for details).</p><p>When false, merge the upstream branch into the current branch.</p><p>When <strong>interactive</strong>, enable the interactive mode of rebase.</p><p>See <strong>pull.rebase</strong>, <strong>branch.&lt;name&gt;.rebase</strong> and <strong>branch.autoSetupRebase</strong> in <strong>git-config</strong>(1) if you want to make <strong>git pull</strong> always use <strong>--rebase</strong> instead of merging.</p><blockquote><p><br> &gt; &gt; <strong>Note</strong></p><p><br> &gt; &gt; This is a potentially <em>dangerous</em> mode of operation. It rewrites history, which does not bode well when you published that history already. Do <strong>not</strong> use this option unless you have read <strong>git-rebase</strong>(1) carefully.</p></blockquote></blockquote><p>--no-rebase</p><blockquote><p>This is shorthand for --rebase=false.</p></blockquote><h3 id="options-related-to-fetching" tabindex="-1">Options related to fetching <a class="header-anchor" href="#options-related-to-fetching" aria-label="Permalink to &quot;Options related to fetching&quot;">​</a></h3><p>--all</p><blockquote><p>Fetch all remotes.</p></blockquote><p>-a, --append</p><blockquote><p>Append ref names and object names of fetched refs to the existing contents of <strong>.git/FETCH_HEAD</strong>. Without this option old data in <strong>.git/FETCH_HEAD</strong> will be overwritten.</p></blockquote><p>--atomic</p><blockquote><p>Use an atomic transaction to update local refs. Either all refs are updated, or on error, no refs are updated.</p></blockquote><p>--depth=&lt;depth&gt;</p><blockquote><p>Limit fetching to the specified number of commits from the tip of each remote branch history. If fetching to a <em>shallow</em> repository created by <strong>git clone</strong> with <strong>--depth=&lt;depth&gt;</strong> option (see <strong>git-clone</strong>(1)), deepen or shorten the history to the specified number of commits. Tags for the deepened commits are not fetched.</p></blockquote><p>--deepen=&lt;depth&gt;</p><blockquote><p>Similar to --depth, except it specifies the number of commits from the current shallow boundary instead of from the tip of each remote branch history.</p></blockquote><p>--shallow-since=&lt;date&gt;</p><blockquote><p>Deepen or shorten the history of a shallow repository to include all reachable commits after &lt;date&gt;.</p></blockquote><p>--shallow-exclude=&lt;revision&gt;</p><blockquote><p>Deepen or shorten the history of a shallow repository to exclude commits reachable from a specified remote branch or tag. This option can be specified multiple times.</p></blockquote><p>--unshallow</p><blockquote><p>If the source repository is complete, convert a shallow repository to a complete one, removing all the limitations imposed by shallow repositories.</p><p>If the source repository is shallow, fetch as much as possible so that the current repository has the same history as the source repository.</p></blockquote><p>--update-shallow</p><blockquote><p>By default when fetching from a shallow repository, <strong>git fetch</strong> refuses refs that require updating .git/shallow. This option updates .git/shallow and accept such refs.</p></blockquote><p>--negotiation-tip=&lt;commit|glob&gt;</p><blockquote><p>By default, Git will report, to the server, commits reachable from all local refs to find common commits in an attempt to reduce the size of the to-be-received packfile. If specified, Git will only report commits reachable from the given tips. This is useful to speed up fetches when the user knows which local ref is likely to have commits in common with the upstream ref being fetched.</p><p>This option may be specified more than once; if so, Git will report commits reachable from any of the given commits.</p><p>The argument to this option may be a glob on ref names, a ref, or the (possibly abbreviated) SHA-1 of a commit. Specifying a glob is equivalent to specifying this option multiple times, one for each matching ref name.</p><p>See also the <strong>fetch.negotiationAlgorithm</strong> and <strong>push.negotiate</strong> configuration variables documented in <strong>git-config</strong>(1), and the <strong>--negotiate-only</strong> option below.</p></blockquote><p>--negotiate-only</p><blockquote><p>Do not fetch anything from the server, and instead print the ancestors of the provided *<em>--negotiation-tip=*</em> * arguments, which we have in common with the server.</p><p>This is incompatible with <strong>--recurse-submodules=[yes|on-demand]</strong>. Internally this is used to implement the <strong>push.negotiate</strong> option, see <strong>git-config</strong>(1).</p></blockquote><p>--dry-run</p><blockquote><p>Show what would be done, without making any changes.</p></blockquote><p>-f, --force</p><blockquote><p>When <em>git fetch</em> is used with <strong>&lt;src&gt;:&lt;dst&gt;</strong> refspec it may refuse to update the local branch as discussed in the <strong>&lt;refspec&gt;</strong> part of the <strong>git-fetch</strong>(1) documentation. This option overrides that check.</p></blockquote><p>-k, --keep</p><blockquote><p>Keep downloaded pack.</p></blockquote><p>--prefetch</p><blockquote><p>Modify the configured refspec to place all refs into the <strong>refs/prefetch/</strong> namespace. See the <strong>prefetch</strong> task in <strong>git-maintenance</strong>(1).</p></blockquote><p>-p, --prune</p><blockquote><p>Before fetching, remove any remote-tracking references that no longer exist on the remote. Tags are not subject to pruning if they are fetched only because of the default tag auto-following or due to a --tags option. However, if tags are fetched due to an explicit refspec (either on the command line or in the remote configuration, for example if the remote was cloned with the --mirror option), then they are also subject to pruning. Supplying <strong>--prune-tags</strong> is a shorthand for providing the tag refspec.</p></blockquote><p>--no-tags</p><blockquote><p>By default, tags that point at objects that are downloaded from the remote repository are fetched and stored locally. This option disables this automatic tag following. The default behavior for a remote may be specified with the remote.&lt;name&gt;.tagOpt setting. See <strong>git-config</strong>(1).</p></blockquote><p>--refmap=&lt;refspec&gt;</p><blockquote><p>When fetching refs listed on the command line, use the specified refspec (can be given more than once) to map the refs to remote-tracking branches, instead of the values of <strong>remote.*.fetch</strong> configuration variables for the remote repository. Providing an empty <strong>&lt;refspec&gt;</strong> to the <strong>--refmap</strong> option causes Git to ignore the configured refspecs and rely entirely on the refspecs supplied as command-line arguments. See section on &quot;Configured Remote-tracking Branches&quot; for details.</p></blockquote><p>-t, --tags</p><blockquote><p>Fetch all tags from the remote (i.e., fetch remote tags *<em>refs/tags/*</em> * into local tags with the same name), in addition to whatever else would otherwise be fetched. Using this option alone does not subject tags to pruning, even if --prune is used (though tags may be pruned anyway if they are also the destination of an explicit refspec; see <strong>--prune</strong>).</p></blockquote><p>-j, --jobs=&lt;n&gt;</p><blockquote><p>Number of parallel children to be used for all forms of fetching.</p><p>If the <strong>--multiple</strong> option was specified, the different remotes will be fetched in parallel. If multiple submodules are fetched, they will be fetched in parallel. To control them independently, use the config settings <strong>fetch.parallel</strong> and <strong>submodule.fetchJobs</strong> (see <strong>git-config</strong>(1)).</p><p>Typically, parallel recursive and multi-remote fetches will be faster. By default fetches are performed sequentially, not in parallel.</p></blockquote><p>--set-upstream</p><blockquote><p>If the remote is fetched successfully, add upstream (tracking) reference, used by argument-less <strong>git-pull</strong>(1) and other commands. For more information, see <strong>branch.&lt;name&gt;.merge</strong> and <strong>branch.&lt;name&gt;.remote</strong> in <strong>git-config</strong>(1).</p></blockquote><p>--upload-pack &lt;upload-pack&gt;</p><blockquote><p>When given, and the repository to fetch from is handled by <em>git fetch-pack</em>, <strong>--exec=&lt;upload-pack&gt;</strong> is passed to the command to specify non-default path for the command run on the other end.</p></blockquote><p>--progress</p><blockquote><p>Progress status is reported on the standard error stream by default when it is attached to a terminal, unless -q is specified. This flag forces progress status even if the standard error stream is not directed to a terminal.</p></blockquote><p>-o &lt;option&gt;, --server-option=&lt;option&gt;</p><blockquote><p>Transmit the given string to the server when communicating using protocol version 2. The given string must not contain a NUL or LF character. The server&#39;s handling of server options, including unknown ones, is server-specific. When multiple <strong>--server-option=&lt;option&gt;</strong> are given, they are all sent to the other side in the order listed on the command line.</p></blockquote><p>--show-forced-updates</p><blockquote><p>By default, git checks if a branch is force-updated during fetch. This can be disabled through fetch.showForcedUpdates, but the --show-forced-updates option guarantees this check occurs. See <strong>git-config</strong>(1).</p></blockquote><p>--no-show-forced-updates</p><blockquote><p>By default, git checks if a branch is force-updated during fetch. Pass --no-show-forced-updates or set fetch.showForcedUpdates to false to skip this check for performance reasons. If used during <em>git-pull</em> the --ff-only option will still check for forced updates before attempting a fast-forward update. See <strong>git-config</strong>(1).</p></blockquote><p>-4, --ipv4</p><blockquote><p>Use IPv4 addresses only, ignoring IPv6 addresses.</p></blockquote><p>-6, --ipv6</p><blockquote><p>Use IPv6 addresses only, ignoring IPv4 addresses.</p></blockquote><p>&lt;repository&gt;</p><blockquote><p>The &quot;remote&quot; repository that is the source of a fetch or pull operation. This parameter can be either a URL (see the section GIT URLS below) or the name of a remote (see the section REMOTES below).</p></blockquote><p>&lt;refspec&gt;</p><blockquote><p>Specifies which refs to fetch and which local refs to update. When no &lt;refspec&gt;s appear on the command line, the refs to fetch are read from <strong>remote.&lt;repository&gt;.fetch</strong> variables instead (see the section &quot;CONFIGURED REMOTE-TRACKING BRANCHES&quot; in <strong>git-fetch</strong>(1)).</p><p>The format of a &lt;refspec&gt; parameter is an optional plus <strong>+</strong>, followed by the source &lt;src&gt;, followed by a colon <strong>:</strong>, followed by the destination ref &lt;dst&gt;. The colon can be omitted when &lt;dst&gt; is empty. &lt;src&gt; is typically a ref, but it can also be a fully spelled hex object name.</p><p>A &lt;refspec&gt; may contain a *<em>*</em> * in its &lt;src&gt; to indicate a simple pattern match. Such a refspec functions like a glob that matches any ref with the same prefix. A pattern &lt;refspec&gt; must have a *<em>*</em> * in both the &lt;src&gt; and &lt;dst&gt;. It will map refs to the destination by replacing the *<em>*</em> * with the contents matched from the source.</p><p>If a refspec is prefixed by <strong>^</strong>, it will be interpreted as a negative refspec. Rather than specifying which refs to fetch or which local refs to update, such a refspec will instead specify refs to exclude. A ref will be considered to match if it matches at least one positive refspec, and does not match any negative refspec. Negative refspecs can be useful to restrict the scope of a pattern refspec so that it will not include specific refs. Negative refspecs can themselves be pattern refspecs. However, they may only contain a &lt;src&gt; and do not specify a &lt;dst&gt;. Fully spelled out hex object names are also not supported.</p><p><strong>tag &lt;tag&gt;</strong> means the same as <strong>refs/tags/&lt;tag&gt;:refs/tags/&lt;tag&gt;</strong>; it requests fetching everything up to the given tag.</p><p>The remote ref that matches &lt;src&gt; is fetched, and if &lt;dst&gt; is not an empty string, an attempt is made to update the local ref that matches it.</p><p>Whether that update is allowed without <strong>--force</strong> depends on the ref namespace it&#39;s being fetched to, the type of object being fetched, and whether the update is considered to be a fast-forward. Generally, the same rules apply for fetching as when pushing, see the <strong>&lt;refspec&gt;...</strong> section of <strong>git-push</strong>(1) for what those are. Exceptions to those rules particular to <em>git fetch</em> are noted below.</p><p>Until Git version 2.20, and unlike when pushing with <strong>git-push</strong>(1), any updates to *<em>refs/tags/*</em> * would be accepted without <strong>+</strong> in the refspec (or <strong>--force</strong>). When fetching, we promiscuously considered all tag updates from a remote to be forced fetches. Since Git version 2.20, fetching to update *<em>refs/tags/*</em> * works the same way as when pushing. I.e. any updates will be rejected without <strong>+</strong> in the refspec (or <strong>--force</strong>).</p><p>Unlike when pushing with <strong>git-push</strong>(1), any updates outside of *<em>refs/{tags,heads}/*</em> * will be accepted without <strong>+</strong> in the refspec (or <strong>--force</strong>), whether that&#39;s swapping e.g. a tree object for a blob, or a commit for another commit that&#39;s doesn&#39;t have the previous commit as an ancestor etc.</p><p>Unlike when pushing with <strong>git-push</strong>(1), there is no configuration which&#39;ll amend these rules, and nothing like a <strong>pre-fetch</strong> hook analogous to the <strong>pre-receive</strong> hook.</p><p>As with pushing with <strong>git-push</strong>(1), all of the rules described above about what&#39;s not allowed as an update can be overridden by adding an the optional leading <strong>+</strong> to a refspec (or using <strong>--force</strong> command line option). The only exception to this is that no amount of forcing will make the *<em>refs/heads/*</em> * namespace accept a non-commit object.</p><blockquote><p><br> &gt; &gt; <strong>Note</strong></p><p><br> &gt; &gt; When the remote branch you want to fetch is known to be rewound and rebased regularly, it is expected that its new tip will not be descendant of its previous tip (as stored in your remote-tracking branch the last time you fetched). You would want to use the <strong>+</strong> sign to indicate non-fast-forward updates will be needed for such branches. There is no way to determine or declare that a branch will be made available in a repository with this behavior; the pulling user simply must know this is the expected usage pattern for a branch.</p></blockquote><blockquote><p><br> &gt; &gt; <strong>Note</strong></p><p><br> &gt; &gt; There is a difference between listing multiple &lt;refspec&gt; directly on <em>git pull</em> command line and having multiple <strong>remote.&lt;repository&gt;.fetch</strong> entries in your configuration for a &lt;repository&gt; and running a <em>git pull</em> command without any explicit &lt;refspec&gt; parameters. &lt;refspec&gt;s listed explicitly on the command line are always merged into the current branch after fetching. In other words, if you list more than one remote ref, <em>git pull</em> will create an Octopus merge. On the other hand, if you do not list any explicit &lt;refspec&gt; parameter on the command line, <em>git pull</em> will fetch all the &lt;refspec&gt;s it finds in the <strong>remote.&lt;repository&gt;.fetch</strong> configuration and merge only the first &lt;refspec&gt; found into the current branch. This is because making an Octopus from remote refs is rarely done, while keeping track of multiple remote heads in one-go by fetching more than one is often useful.</p></blockquote></blockquote><h2 id="git-urls" tabindex="-1">GIT URLS <a class="header-anchor" href="#git-urls" aria-label="Permalink to &quot;GIT URLS&quot;">​</a></h2><p>In general, URLs contain information about the transport protocol, the address of the remote server, and the path to the repository. Depending on the transport protocol, some of this information may be absent.</p><p>Git supports ssh, git, http, and https protocols (in addition, ftp, and ftps can be used for fetching, but this is inefficient and deprecated; do not use it).</p><p>The native transport (i.e. git:// URL) does no authentication and should be used with caution on unsecured networks.</p><p>The following syntaxes may be used with them:</p><blockquote><p>·</p><p>ssh://[user@]host.xz[:port]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>git://host.xz[:port]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>http[s]😕/host.xz[:port]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>ftp[s]😕/host.xz[:port]/path/to/repo.git/</p></blockquote><p>An alternative scp-like syntax may also be used with the ssh protocol:</p><blockquote><p>·</p><p>[user@]host.xz:path/to/repo.git/</p></blockquote><p>This syntax is only recognized if there are no slashes before the first colon. This helps differentiate a local path that contains a colon. For example the local path <strong>foo:bar</strong> could be specified as an absolute path or <strong>./foo:bar</strong> to avoid being misinterpreted as an ssh url.</p><p>The ssh and git protocols additionally support ~username expansion:</p><blockquote><p>·</p><p>ssh://[user@]host.xz[:port]/~[user]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>git://host.xz[:port]/~[user]/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>[user@]host.xz:/~[user]/path/to/repo.git/</p></blockquote><p>For local repositories, also supported by Git natively, the following syntaxes may be used:</p><blockquote><p>·</p><p>/path/to/repo.git/</p></blockquote><blockquote><p>·</p><p>file:///path/to/repo.git/</p></blockquote><p>These two syntaxes are mostly equivalent, except when cloning, when the former implies --local option. See <strong>git-clone</strong>(1) for details.</p><p><em>git clone</em>, <em>git fetch</em> and <em>git pull</em>, but not <em>git push</em>, will also accept a suitable bundle file. See <strong>git-bundle</strong>(1).</p><p>When Git doesn&#39;t know how to handle a certain transport protocol, it attempts to use the <em>remote-&lt;transport&gt;</em> remote helper, if one exists. To explicitly request a remote helper, the following syntax may be used:</p><blockquote><p>·</p><p>&lt;transport&gt;::&lt;address&gt;</p></blockquote><p>where &lt;address&gt; may be a path, a server and path, or an arbitrary URL-like string recognized by the specific remote helper being invoked. See <strong>gitremote-helpers</strong>(7) for details.</p><p>If there are a large number of similarly-named remote repositories and you want to use a different format for them (such that the URLs you use will be rewritten into URLs that work), you can create a configuration section of the form:</p><blockquote><pre><code>        [url &quot;&lt;actual url base&gt;&quot;]
                insteadOf = &lt;other url base&gt;
</code></pre></blockquote><p>For example, with this:</p><blockquote><pre><code>        [url &quot;git://git.host.xz/&quot;]
                insteadOf = host.xz:/path/to/
                insteadOf = work:
</code></pre></blockquote><p>a URL like &quot;work:repo.git&quot; or like &quot;host.xz:/path/to/repo.git&quot; will be rewritten in any context that takes a URL to be &quot;git://git.host.xz/repo.git&quot;.</p><p>If you want to rewrite URLs for push only, you can create a configuration section of the form:</p><blockquote><pre><code>        [url &quot;&lt;actual url base&gt;&quot;]
                pushInsteadOf = &lt;other url base&gt;
</code></pre></blockquote><p>For example, with this:</p><blockquote><pre><code>        [url &quot;ssh://example.org/&quot;]
                pushInsteadOf = git://example.org/
</code></pre></blockquote><p>a URL like &quot;git://example.org/path/to/repo.git&quot; will be rewritten to &quot;ssh://example.org/path/to/repo.git&quot; for pushes, but pulls will still use the original URL.</p><h2 id="remotes" tabindex="-1">REMOTES <a class="header-anchor" href="#remotes" aria-label="Permalink to &quot;REMOTES&quot;">​</a></h2><p>The name of one of the following can be used instead of a URL as <strong>&lt;repository&gt;</strong> argument:</p><blockquote><p>·</p><p>a remote in the Git configuration file: <strong>$GIT_DIR/config</strong>,</p></blockquote><blockquote><p>·</p><p>a file in the <strong>$GIT_DIR/remotes</strong> directory, or</p></blockquote><blockquote><p>·</p><p>a file in the <strong>$GIT_DIR/branches</strong> directory.</p></blockquote><p>All of these also allow you to omit the refspec from the command line because they each contain a refspec which git will use by default.</p><h3 id="named-remote-in-configuration-file" tabindex="-1">Named remote in configuration file <a class="header-anchor" href="#named-remote-in-configuration-file" aria-label="Permalink to &quot;Named remote in configuration file&quot;">​</a></h3><p>You can choose to provide the name of a remote which you had previously configured using <strong>git-remote</strong>(1), <strong>git-config</strong>(1) or even by a manual edit to the <strong>$GIT_DIR/config</strong> file. The URL of this remote will be used to access the repository. The refspec of this remote will be used by default when you do not provide a refspec on the command line. The entry in the config file would appear like this:</p><blockquote><pre><code>        [remote &quot;&lt;name&gt;&quot;]
                url = &lt;URL&gt;
                pushurl = &lt;pushurl&gt;
                push = &lt;refspec&gt;
                fetch = &lt;refspec&gt;
</code></pre></blockquote><p>The <strong>&lt;pushurl&gt;</strong> is used for pushes only. It is optional and defaults to <strong>&lt;URL&gt;</strong>. Pushing to a remote affects all defined pushurls or to all defined urls if no pushurls are defined. Fetch, however, will only fetch from the first defined url if muliple urls are defined.</p><h3 id="named-file-in-git-dir-remotes" tabindex="-1">Named file in <strong>$GIT_DIR/remotes</strong> <a class="header-anchor" href="#named-file-in-git-dir-remotes" aria-label="Permalink to &quot;Named file in **\\$GIT_DIR/remotes**&quot;">​</a></h3><p>You can choose to provide the name of a file in <strong>$GIT_DIR/remotes</strong>. The URL in this file will be used to access the repository. The refspec in this file will be used as default when you do not provide a refspec on the command line. This file should have the following format:</p><blockquote><pre><code>        URL: one of the above URL format
        Push: &lt;refspec&gt;
        Pull: &lt;refspec&gt;
</code></pre></blockquote><p><strong>Push:</strong> lines are used by <em>git push</em> and <strong>Pull:</strong> lines are used by <em>git pull</em> and <em>git fetch</em>. Multiple <strong>Push:</strong> and <strong>Pull:</strong> lines may be specified for additional branch mappings.</p><h3 id="named-file-in-git-dir-branches" tabindex="-1">Named file in <strong>$GIT_DIR/branches</strong> <a class="header-anchor" href="#named-file-in-git-dir-branches" aria-label="Permalink to &quot;Named file in **\\$GIT_DIR/branches**&quot;">​</a></h3><p>You can choose to provide the name of a file in <strong>$GIT_DIR/branches</strong>. The URL in this file will be used to access the repository. This file should have the following format:</p><blockquote><pre><code>        &lt;URL&gt;#&lt;head&gt;
</code></pre></blockquote><p><strong>&lt;URL&gt;</strong> is required; <strong>#&lt;head&gt;</strong> is optional.</p><p>Depending on the operation, git will use one of the following refspecs, if you don&#39;t provide one on the command line. <strong>&lt;branch&gt;</strong> is the name of this file in <strong>$GIT_DIR/branches</strong> and <strong>&lt;head&gt;</strong> defaults to <strong>master</strong>.</p><p>git fetch uses:</p><blockquote><pre><code>        refs/heads/&lt;head&gt;:refs/heads/&lt;branch&gt;
</code></pre></blockquote><p>git push uses:</p><blockquote><pre><code>        HEAD:refs/heads/&lt;head&gt;
</code></pre></blockquote><h2 id="merge-strategies" tabindex="-1">MERGE STRATEGIES <a class="header-anchor" href="#merge-strategies" aria-label="Permalink to &quot;MERGE STRATEGIES&quot;">​</a></h2><p>The merge mechanism (<strong>git merge</strong> and <strong>git pull</strong> commands) allows the backend <em>merge strategies</em> to be chosen with <strong>-s</strong> option. Some strategies can also take their own options, which can be passed by giving <strong>-X&lt;option&gt;</strong> arguments to <strong>git merge</strong> and/or <strong>git pull</strong>.</p><p>ort</p><blockquote><p>This is the default merge strategy when pulling or merging one branch. This strategy can only resolve two heads using a 3-way merge algorithm. When there is more than one common ancestor that can be used for 3-way merge, it creates a merged tree of the common ancestors and uses that as the reference tree for the 3-way merge. This has been reported to result in fewer merge conflicts without causing mismerges by tests done on actual merge commits taken from Linux 2.6 kernel development history. Additionally this strategy can detect and handle merges involving renames. It does not make use of detected copies. The name for this algorithm is an acronym (&quot;Ostensibly Recursive&#39;s Twin&quot;) and came from the fact that it was written as a replacement for the previous default algorithm, <strong>recursive</strong>.</p><p>The <em>ort</em> strategy can take the following options:</p><p>ours</p><blockquote><p>This option forces conflicting hunks to be auto-resolved cleanly by favoring <em>our</em> version. Changes from the other tree that do not conflict with our side are reflected in the merge result. For a binary file, the entire contents are taken from our side.</p><p>This should not be confused with the <em>ours</em> merge strategy, which does not even look at what the other tree contains at all. It discards everything the other tree did, declaring <em>our</em> history contains all that happened in it.</p></blockquote><p>theirs</p><blockquote><p>This is the opposite of <em>ours</em>; note that, unlike <em>ours</em>, there is no <em>theirs</em> merge strategy to confuse this merge option with.</p></blockquote><p>ignore-space-change, ignore-all-space, ignore-space-at-eol, ignore-cr-at-eol</p><blockquote><p>Treats lines with the indicated type of whitespace change as unchanged for the sake of a three-way merge. Whitespace changes mixed with other changes to a line are not ignored. See also <strong>git-diff</strong>(1) <strong>-b</strong>, <strong>-w</strong>, <strong>--ignore-space-at-eol</strong>, and <strong>--ignore-cr-at-eol</strong>.</p><blockquote><p>·</p><p>If <em>their</em> version only introduces whitespace changes to a line, <em>our</em> version is used;</p></blockquote><blockquote><p>·</p><p>If <em>our</em> version introduces whitespace changes but <em>their</em> version includes a substantial change, <em>their</em> version is used;</p></blockquote><blockquote><p>·</p><p>Otherwise, the merge proceeds in the usual way.</p></blockquote></blockquote><p>renormalize</p><blockquote><p>This runs a virtual check-out and check-in of all three stages of a file when resolving a three-way merge. This option is meant to be used when merging branches with different clean filters or end-of-line normalization rules. See &quot;Merging branches with differing checkin/checkout attributes&quot; in <strong>gitattributes</strong>(5) for details.</p></blockquote><p>no-renormalize</p><blockquote><p>Disables the <strong>renormalize</strong> option. This overrides the <strong>merge.renormalize</strong> configuration variable.</p></blockquote><p>find-renames[=&lt;n&gt;]</p><blockquote><p>Turn on rename detection, optionally setting the similarity threshold. This is the default. This overrides the <em>merge.renames</em> configuration variable. See also <strong>git-diff</strong>(1) <strong>--find-renames</strong>.</p></blockquote><p>rename-threshold=&lt;n&gt;</p><blockquote><p>Deprecated synonym for <strong>find-renames=&lt;n&gt;</strong>.</p></blockquote><p>subtree[=&lt;path&gt;]</p><blockquote><p>This option is a more advanced form of <em>subtree</em> strategy, where the strategy makes a guess on how two trees must be shifted to match with each other when merging. Instead, the specified path is prefixed (or stripped from the beginning) to make the shape of two trees to match.</p></blockquote></blockquote><p>recursive</p><blockquote><p>This can only resolve two heads using a 3-way merge algorithm. When there is more than one common ancestor that can be used for 3-way merge, it creates a merged tree of the common ancestors and uses that as the reference tree for the 3-way merge. This has been reported to result in fewer merge conflicts without causing mismerges by tests done on actual merge commits taken from Linux 2.6 kernel development history. Additionally this can detect and handle merges involving renames. It does not make use of detected copies. This was the default strategy for resolving two heads from Git v0.99.9k until v2.33.0.</p><p>The <em>recursive</em> strategy takes the same options as <em>ort</em>. However, there are three additional options that <em>ort</em> ignores (not documented above) that are potentially useful with the <em>recursive</em> strategy:</p><p>patience</p><blockquote><p>Deprecated synonym for <strong>diff-algorithm=patience</strong>.</p></blockquote><p>diff-algorithm=[patience|minimal|histogram|myers]</p><blockquote><p>Use a different diff algorithm while merging, which can help avoid mismerges that occur due to unimportant matching lines (such as braces from distinct functions). See also <strong>git-diff</strong>(1) <strong>--diff-algorithm</strong>. Note that <strong>ort</strong> specifically uses <strong>diff-algorithm=histogram</strong>, while <strong>recursive</strong> defaults to the <strong>diff.algorithm</strong> config setting.</p></blockquote><p>no-renames</p><blockquote><p>Turn off rename detection. This overrides the <strong>merge.renames</strong> configuration variable. See also <strong>git-diff</strong>(1) <strong>--no-renames</strong>.</p></blockquote></blockquote><p>resolve</p><blockquote><p>This can only resolve two heads (i.e. the current branch and another branch you pulled from) using a 3-way merge algorithm. It tries to carefully detect criss-cross merge ambiguities. It does not handle renames.</p></blockquote><p>octopus</p><blockquote><p>This resolves cases with more than two heads, but refuses to do a complex merge that needs manual resolution. It is primarily meant to be used for bundling topic branch heads together. This is the default merge strategy when pulling or merging more than one branch.</p></blockquote><p>ours</p><blockquote><p>This resolves any number of heads, but the resulting tree of the merge is always that of the current branch head, effectively ignoring all changes from all other branches. It is meant to be used to supersede old development history of side branches. Note that this is different from the -Xours option to the <em>recursive</em> merge strategy.</p></blockquote><p>subtree</p><blockquote><p>This is a modified <strong>ort</strong> strategy. When merging trees A and B, if B corresponds to a subtree of A, B is first adjusted to match the tree structure of A, instead of reading the trees at the same level. This adjustment is also done to the common ancestor tree.</p></blockquote><p>With the strategies that use 3-way merge (including the default, <em>ort</em>), if a change is made on both branches, but later reverted on one of the branches, that change will be present in the merged result; some people find this behavior confusing. It occurs because only the heads and the merge base are considered when performing a merge, not the individual commits. The merge algorithm therefore considers the reverted change as no change at all, and substitutes the changed version instead.</p><h2 id="default-behaviour" tabindex="-1">DEFAULT BEHAVIOUR <a class="header-anchor" href="#default-behaviour" aria-label="Permalink to &quot;DEFAULT BEHAVIOUR&quot;">​</a></h2><p>Often people use <strong>git pull</strong> without giving any parameter. Traditionally, this has been equivalent to saying <strong>git pull origin</strong>. However, when configuration <strong>branch.&lt;name&gt;.remote</strong> is present while on branch <strong>&lt;name&gt;</strong>, that value is used instead of <strong>origin</strong>.</p><p>In order to determine what URL to use to fetch from, the value of the configuration <strong>remote.&lt;origin&gt;.url</strong> is consulted and if there is not any such variable, the value on the <strong>URL:</strong> line in <strong>$GIT_DIR/remotes/&lt;origin&gt;</strong> is used.</p><p>In order to determine what remote branches to fetch (and optionally store in the remote-tracking branches) when the command is run without any refspec parameters on the command line, values of the configuration variable <strong>remote.&lt;origin&gt;.fetch</strong> are consulted, and if there aren&#39;t any, <strong>$GIT_DIR/remotes/&lt;origin&gt;</strong> is consulted and its <strong>Pull:</strong> lines are used. In addition to the refspec formats described in the OPTIONS section, you can have a globbing refspec that looks like this:</p><blockquote><pre><code>refs/heads/*:refs/remotes/origin/*
</code></pre></blockquote><p>A globbing refspec must have a non-empty RHS (i.e. must store what were fetched in remote-tracking branches), and its LHS and RHS must end with *<em>/*</em> *. The above specifies that all remote branches are tracked using remote-tracking branches in <strong>refs/remotes/origin/</strong> hierarchy under the same name.</p><p>The rule to determine which remote branch to merge after fetching is a bit involved, in order not to break backward compatibility.</p><p>If explicit refspecs were given on the command line of <strong>git pull</strong>, they are all merged.</p><p>When no refspec was given on the command line, then <strong>git pull</strong> uses the refspec from the configuration or <strong>$GIT_DIR/remotes/&lt;origin&gt;</strong>. In such cases, the following rules apply:</p><blockquote><p>1.</p><p>If <strong>branch.&lt;name&gt;.merge</strong> configuration for the current branch <strong>&lt;name&gt;</strong> exists, that is the name of the branch at the remote site that is merged.</p></blockquote><blockquote><p>2.</p><p>If the refspec is a globbing one, nothing is merged.</p></blockquote><blockquote><p>3.</p><p>Otherwise the remote branch of the first refspec is merged.</p></blockquote><h2 id="examples" tabindex="-1">EXAMPLES <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;EXAMPLES&quot;">​</a></h2><blockquote><p>·</p><p>Update the remote-tracking branches for the repository you cloned from, then merge one of them into your current branch:</p><blockquote><pre><code>$ git pull
$ git pull origin
</code></pre></blockquote><p>Normally the branch merged in is the HEAD of the remote repository, but the choice is determined by the branch.&lt;name&gt;.remote and branch.&lt;name&gt;.merge options; see <strong>git-config</strong>(1) for details.</p></blockquote><blockquote><p>·</p><p>Merge into the current branch the remote branch <strong>next</strong>:</p><blockquote><pre><code>$ git pull origin next
</code></pre></blockquote><p>This leaves a copy of <strong>next</strong> temporarily in FETCH_HEAD, and updates the remote-tracking branch <strong>origin/next</strong>. The same can be done by invoking fetch and merge:</p><blockquote><pre><code>$ git fetch origin
$ git merge origin/next
</code></pre></blockquote></blockquote><p>If you tried a pull which resulted in complex conflicts and would want to start over, you can recover with <em>git reset</em>.</p><h2 id="security" tabindex="-1">SECURITY <a class="header-anchor" href="#security" aria-label="Permalink to &quot;SECURITY&quot;">​</a></h2><p>The fetch and push protocols are not designed to prevent one side from stealing data from the other repository that was not intended to be shared. If you have private data that you need to protect from a malicious peer, your best option is to store it in another repository. This applies to both clients and servers. In particular, namespaces on a server are not effective for read access control; you should only grant read access to a namespace to clients that you would trust with read access to the entire repository.</p><p>The known attack vectors are as follows:</p><blockquote><p>1.</p><p>The victim sends &quot;have&quot; lines advertising the IDs of objects it has that are not explicitly intended to be shared but can be used to optimize the transfer if the peer also has them. The attacker chooses an object ID X to steal and sends a ref to X, but isn&#39;t required to send the content of X because the victim already has it. Now the victim believes that the attacker has X, and it sends the content of X back to the attacker later. (This attack is most straightforward for a client to perform on a server, by creating a ref to X in the namespace the client has access to and then fetching it. The most likely way for a server to perform it on a client is to &quot;merge&quot; X into a public branch and hope that the user does additional work on this branch and pushes it back to the server without noticing the merge.)</p></blockquote><blockquote><p>2.</p><p>As in #1, the attacker chooses an object ID X to steal. The victim sends an object Y that the attacker already has, and the attacker falsely claims to have X and not Y, so the victim sends Y as a delta against X. The delta reveals regions of X that are similar to Y to the attacker.</p></blockquote><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Using --recurse-submodules can only fetch new commits in already checked out submodules right now. When e.g. upstream added a new submodule in the just fetched commits of the superproject the submodule itself cannot be fetched, making it impossible to check out that submodule later without having to do a fetch again. This is expected to be fixed in a future Git version.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>git-fetch</strong>(1), <strong>git-merge</strong>(1), <strong>git-config</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,222))])}const b=o(h,[["render",c]]);export{f as __pageData,b as default};
